import {STATUS,composePostText,LANGUAGES,CITIES,initials,canonicalStatus,recommended} from './domain.mjs';
import {esc,icon,btn,date,number,directions,workLink,formLink} from './ui.mjs';
const badge=a=>`<span class="status ${STATUS[canonicalStatus(a.status)]?.tone||'neutral'}"><i></i>${STATUS[canonicalStatus(a.status)]?.label||'Заявка'}</span>`;
const brandText=v=>String(v||'').replace(/СНЕГ\*?|SNEG\*/gi,'SNEG');
const brand=()=>`<a class="brand" href="/" aria-label="SNEG — главная">SNEG</a>`;
const navs=[['review','people','Отбор'],['posts','threads','Threads'],['settings','settings','Настройки']];
export function layout(s,demo){
 const team=s.user.role!=='candidate',role=team?'Менеджер':'Кандидат';
 return `${demo?`<div class="demo-bar"><span>Просмотр · вымышленные данные</span><button data-role-switch>${team?'Анкета кандидата':'Кабинет менеджера'} ${icon('arrow')}</button></div>`:''}
 <header class="topbar">${brand()}${team?`<nav class="desktop-nav" aria-label="Разделы">${navs.map(([id,ic,label])=>`<button class="${s.view===id?'active':''}" data-view="${id}" ${s.view===id?'aria-current="page"':''}>${label}</button>`).join('')}</nav>`:''}
 <div class="topbar-end"><button class="icon-button" data-refresh aria-label="Обновить">${icon('refresh')}</button><button class="account-button" data-account aria-label="Аккаунт: ${esc(s.user.name||'Вы')}, ${role}"><span class="account-role">${role}</span><span class="initials">${esc(initials(s.user.name||'Вы'))}</span></button></div></header>
 <main id="main" class="page ${team?'manager-page':'candidate-page'}"></main>${team?`<nav class="mobile-nav" aria-label="Разделы">${navs.map(([id,ic,label])=>`<button data-view="${id}" class="${s.view===id?'active':''}" ${s.view===id?'aria-current="page"':''}>${icon(ic)}<span>${label}</span></button>`).join('')}</nav>`:''}`;
}
export function queueView(s){
 const tabs=[['all_new','Новые',s.stats.review],['recommended','Рекомендации',s.stats.recommended],['waiting','Уточнения',s.stats.clarification],['selected','Выбранные',s.stats.selected],['archive','История',null]];
 const searching=!!s.search.trim(),emptyTitle=searching?'Ничего не найдено':s.bucket==='recommended'?'Пока без рекомендаций':s.bucket==='waiting'?'Нет ожидающих ответов':s.bucket==='selected'?'Пока никто не выбран':s.bucket==='archive'?'История пуста':'Новых заявок нет';
 const emptyAction=searching?btn('Сбросить поиск','data-clear-search','secondary'):s.bucket==='recommended'?btn('Все новые заявки','data-bucket="all_new"','secondary'):s.bucket==='all_new'?btn('Создать пост','data-view="posts"','secondary'):'';
 return `<section class="page-head queue-head"><h1>Заявки</h1>${btn('Ссылка на анкету',`data-copy="${esc(formLink(s.botUsername))}"`,'secondary','copy')}</section>
 <section class="queue" aria-label="Заявки креаторов">
 <div class="queue-tabs" role="tablist" aria-label="Очереди">${tabs.map(([key,label,n])=>`<button role="tab" aria-selected="${s.bucket===key}" data-bucket="${key}" class="${s.bucket===key?'active':''}">${label}${n!==null?`<span>${n||0}</span>`:''}</button>`).join('')}</div>
 <div class="queue-tools"><label class="search">${icon('search')}<input type="search" data-search value="${esc(s.search)}" placeholder="Имя или номер заявки" aria-label="Поиск кандидатов"></label><select data-direction aria-label="Формат сотрудничества" ${searching?'disabled title="Поиск по всем форматам"':''}><option value="">Все форматы</option><option value="ugc" ${!searching&&s.direction==='ugc'?'selected':''}>UGC</option><option value="reach" ${!searching&&s.direction==='reach'?'selected':''}>Охваты</option></select></div>
 <div class="queue-label"><span>${number(s.total)} ${searching?'найдено по всей базе':'заявок'}</span><span>По приоритету</span></div>
 <div class="candidate-list">${s.rows.length?s.rows.map(candidateCard).join(''):`<div class="empty"><h2>${emptyTitle}</h2>${searching?'<p>Попробуйте другое имя или номер.</p>':''}${emptyAction}</div>`}</div>
 ${s.hasMore?btn('Показать ещё','data-more','secondary full','plus'):''}
 <div class="queue-foot">${btn('Обновить подборку в боте','data-shortlist','text','refresh')}</div></section>`;
}
function candidateCard(a){const ai=a.evaluation?.ai,reason=ai?.summary||a.evaluation?.summary||'Нужен просмотр анкеты';return `<article class="candidate" data-candidate-id="${a.id}"><div class="candidate-top"><span class="candidate-number">${a.id}</span><div class="pills">${directions(a)}${a.status==='review'?'':badge(a)}</div></div><div class="candidate-body"><div class="candidate-person"><span class="portrait">${esc(initials(a.name))}</span><div><button class="name-link" data-detail="${a.id}"><h2>${esc(a.name)}</h2></button><p>${esc(a.city)}<span>·</span>${LANGUAGES[a.language]}</p></div></div><div class="candidate-reason"><span class="eyebrow">${ai?'Оценка ИИ':'По анкете'}</span><p>${esc(reason)}</p>${a.evaluation?.aiStatus==='pending'?'<span class="fine">ИИ готовит резюме</span>':''}</div></div><div class="candidate-bottom"><div>${a.portfolio[0]?workLink(a.portfolio[0]):'<span class="fine">Пример пока не приложен</span>'}</div>${btn('Открыть анкету',`data-detail="${a.id}"`,'text','arrow')}</div></article>`;}
function threadsConnection(s){const c=s.connections;return `<aside class="threads-connect"><div class="connection-title">${icon('threads')}<h2>${c.threads?'@'+esc(c.threadsUsername||'аккаунт'):'Подключить Threads'}</h2></div>${!c.threads?'<p>Добавьте аккаунт для публикаций.</p>':''}${c.threads?`<span class="status olive"><i></i>Подключён</span>${c.threadsExpiresAt?'<p class="fine">Доступ до '+date(c.threadsExpiresAt)+'</p>':''}${s.user.role==='admin'?'<details><summary>Управление доступом</summary>'+btn('Отключить Threads','data-disconnect','text')+'</details>':''}`:s.user.role!=='admin'?'<p class="fine">Подключение настраивает владелец пространства.</p>':`<div class="setup-step"><b>01</b><div><h3>Приложение Meta</h3><p>В Meta for Developers создайте приложение с Threads API. Выберите сценарий «Access the Threads API». Добавьте аккаунт бренда в роли Threads Tester и примите приглашение в настройках Threads.</p><a class="text-button" href="https://developers.facebook.com/apps/" target="_blank" rel="noopener">Открыть Meta ${icon('external')}</a></div></div><div class="setup-step"><b>02</b><div><h3>Адрес возврата</h3><p>Добавьте этот адрес в Valid OAuth Redirect URIs приложения Meta.</p><div class="copy-field"><code>${esc(c.callbackUrl||'Откройте рабочий кабинет в Telegram')}</code><button class="icon-button" data-copy="${esc(c.callbackUrl||'')}" aria-label="Копировать адрес">${icon('copy')}</button></div></div></div><form data-form="threads-app" class="stack"><label>Threads App ID<input name="appId" inputmode="numeric" autocomplete="off" required placeholder="Из настроек приложения Meta"></label><label>Threads App Secret<input type="password" name="appSecret" autocomplete="new-password" required placeholder="Сохраняется только на сервере"></label>${btn(c.threadsAppReady?'Обновить приложение':'Сохранить настройки','type="submit"','secondary full')}</form>${btn('Войти в Threads',`data-authorize ${!c.threadsAppReady?'disabled':''}`,'primary full','arrow')}<details class="token-alternative"><summary>Уже есть Threads Access Token?</summary><form data-form="threads-token" class="stack"><p class="fine">Нужен Threads User Token с threads_basic и threads_content_publish. Facebook/Instagram Token не подойдёт.</p><label>Threads Access Token<input type="password" name="token" autocomplete="new-password" required></label>${btn('Проверить и подключить','type="submit"','secondary full')}</form></details>`}${c.threadsError?'<p class="inline-error">'+esc(c.threadsError)+'</p>':''}</aside>`;}
export function postsView(s){const p=s.postDraft;return `<section class="page-head"><div><h1>Публикации</h1></div><span class="status ${s.connections.threads?'olive':'neutral'}"><i></i>${s.connections.threads?'@'+esc(s.connections.threadsUsername||'Threads'):'Аккаунт не подключён'}</span></section><div class="threads-grid"><section><form class="post-editor" data-form="post"><div class="section-top"><span class="eyebrow">Новый пост</span><button type="button" class="text-button" data-post-template>Шаблон ${icon('plus')}</button></div><label class="sr-only" for="post-text">Текст публикации</label><textarea id="post-text" name="text" maxlength="500" rows="8" placeholder="Расскажите, кого ищет ваш бренд…">${esc(p.text)}</textarea><div class="editor-meta"><label class="check-line"><input type="checkbox" name="includeForm" ${p.includeForm!==false?'checked':''}>Добавить ссылку на анкету</label><span data-post-count>${[...composePostText(p.text,formLink(s.botUsername),p.includeForm!==false)].length} / 500</span></div><label class="schedule-label">Когда опубликовать<input type="datetime-local" name="scheduledAt" value="${esc(p.scheduledAt||'')}"></label><p class="fine">Время вашего устройства: ${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}.</p><div class="editor-actions">${btn('Сохранить черновик','type="submit" name="intent" value="draft"','secondary')}${btn('Запланировать',`type="submit" name="intent" value="scheduled" ${!s.connections.threads?'disabled':''}`,'primary','arrow')}</div>${!s.connections.threads?'<p class="fine">Для публикации подключите Threads.</p>':''}</form><section class="post-list"><div class="section-top"><h2>План публикаций</h2><span>${s.posts.length}</span></div>${s.posts.length?s.posts.map(postRow).join(''):'<div class="empty small"><p>Первая публикация начнётся с вашего текста.</p></div>'}</section></section>${threadsConnection(s)}</div>`;}
function postRow(p){const labels={draft:'Черновик',scheduled:'В расписании',publishing:'Публикуется',published:'Опубликован',failed:'Нужна проверка',needs_check:'Проверьте аккаунт'};return `<article class="post-row"><div class="post-meta"><span class="status ${p.status==='published'?'olive':'neutral'}"><i></i>${labels[p.status]||p.status}</span><span>${date(p.scheduledAt||p.createdAt)}</span></div><p>${esc(p.text)}</p>${p.error?'<p class="inline-error">'+esc(p.error)+'</p>':''}<div class="post-row-actions">${['draft','scheduled','failed'].includes(p.status)?btn('Редактировать',`data-edit-post="${p.id}"`,'text'):''}${['draft','failed'].includes(p.status)?btn('Опубликовать сейчас',`data-publish="${p.id}"`,'text','arrow'):''}${p.status==='scheduled'?btn('Снять с расписания',`data-cancel-post="${p.id}"`,'text'):''}${p.permalink?`<a class="text-button" href="${esc(p.permalink)}" target="_blank" rel="noopener">Открыть в Threads ${icon('external')}</a>`:''}</div></article>`;}
export function settingsView(s){const c=s.campaign,admin=s.user.role==='admin';return `<section class="page-head"><div><h1>Настройки</h1></div></section><div class="settings-grid"><section class="settings-section"><h2>Условия</h2><form data-form="campaign" class="stack"><label>Название набора<input name="name" value="${esc(c.name)}" required ${!admin?'disabled':''}></label><label>Условия сотрудничества<textarea rows="5" name="brief" required ${!admin?'disabled':''}>${esc(brandText(c.brief))}</textarea></label><div class="two-fields"><label>Сколько креаторов выбираем<input type="number" min="1" max="100000" name="limit" value="${c.limit}" ${!admin?'disabled':''}></label><label>Ориентир просмотров для охватов<input type="number" min="0" name="minViews" value="${c.minViews??1000}" ${!admin?'disabled':''}></label></div><p class="fine">Для UGC количество подписчиков не участвует в отборе. Охваты оцениваются отдельно по просмотрам и аудитории.</p><label class="check-line"><input name="active" type="checkbox" ${c.active?'checked':''} ${!admin?'disabled':''}>Принимать новые анкеты</label><details><summary>Условия для рабочего набора</summary><div class="stack"><label>Оператор данных<input name="operator" value="${esc(c.operator||'')}" ${!admin?'disabled':''}></label><label>Ссылка на политику<input type="url" name="privacyUrl" value="${esc(c.privacyUrl||'')}" ${!admin?'disabled':''}></label><label class="check-line"><input name="productionApproved" type="checkbox" ${c.productionApproved?'checked':''} ${!admin?'disabled':''}>Условия и политика утверждены владельцем</label></div></details>${admin?btn('Сохранить условия','type="submit"','primary'):''}</form></section><section class="settings-section ai-panel"><h2>Оценка анкет</h2><div class="connection-state"><span class="status ${s.connections.aiConnected?'olive':'neutral'}"><i></i>${s.connections.aiConnected?'Подключён '+esc(s.connections.aiModel):'Пока работают только правила'}</span></div>${admin?`<form data-form="ai" class="stack"><label>Ключ Google AI Studio<input name="key" type="password" autocomplete="new-password" placeholder="Вставьте ключ здесь, не в чат" required></label><details><summary>Выбрать модель вручную</summary><label>Имя модели<input name="model" placeholder="По умолчанию — доступная модель Flash"></label></details><p class="fine">Бесплатная квота зависит от аккаунта и модели. Контакты, имя, адреса и ссылки на работы модели не передаются. Видео она не просматривает.</p>${btn('Проверить и подключить','type="submit"','primary full','arrow')}</form>${s.connections.aiConnected?btn('Оставить только правила','data-ai-disable','text'):''}`:'<p class="fine">Ключ модели добавляет владелец пространства.</p>'}<div class="quiet-note"><h3>Подборка вместо потока</h3><p>О новых анкетах приходит уведомление, не чаще одного раза в 15 минут. Общая подборка обновляется в том же сообщении. Все заявки доступны в очереди.</p></div></section></div>`;}
export function detailView(s){const a=s.detail;if(!a)return '';const ai=a.evaluation?.ai;return `<div class="drawer-backdrop" data-close-detail></div><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="candidate-title"><header class="drawer-top"><span>${a.id}</span><button class="icon-button" data-close-detail aria-label="Закрыть карточку">${icon('close')}</button></header><div class="drawer-scroll"><div class="drawer-heading"><span class="eyebrow">${esc(a.city)} / ${LANGUAGES[a.language]}</span><h2 id="candidate-title">${esc(a.name)}</h2><div class="pills">${directions(a)}${badge(a)}</div>${s.connections.demo?'<span class="fine">Контакт появится в рабочей анкете</span>':a.username?`<a class="contact-link" href="https://t.me/${esc(a.username)}" target="_blank" rel="noopener">@${esc(a.username)} ${icon('external')}</a>`:/^\d+$/.test(a.telegramId)?`<a class="contact-link" href="tg://user?id=${esc(a.telegramId)}">Открыть в Telegram ${icon('external')}</a><p class="fine">Если Telegram не открывает профиль без имени пользователя, запросите контакт уточнением через бота.</p>`:''}</div><section class="detail-section"><div class="section-top"><h3>Первый взгляд</h3><span class="pill">${ai?'ИИ':'По анкете'}</span></div><p class="summary">${esc(ai?.summary||a.evaluation?.summary)}</p><ul class="reason-list">${(ai?.reasons||a.evaluation?.reasons||[]).map(x=>`<li>${icon('check')}${esc(x)}</li>`).join('')}</ul><div class="unknowns"><span class="eyebrow">ЧТО ПРОВЕРИТЬ</span>${(ai?.unknowns||a.evaluation?.unknowns||[]).map(x=>'<p>'+esc(x)+'</p>').join('')}</div></section><section class="detail-section"><h3>Работы</h3>${a.portfolio.length?a.portfolio.map(workLink).join(''):'<p class="fine">Кандидат пока не приложил работу. Можно запросить один пример.</p>'}${a.profile?a.profile.includes('example.com')?'<button class="text-button" data-demo-work>Профиль · демо</button>':`<a class="text-button" href="${esc(a.profile)}" target="_blank" rel="noopener">Профиль ${icon('external')}</a>`:''}</section><section class="detail-section facts"><div><span>Опыт</span><strong>${({brand:'Снимал(а) для брендов',blog:'Снимает для своего блога',beginner:'Первые проекты'})[a.experience]}</strong></div><div><span>Готовность</span><strong>За ${a.availabilityDays} дней</strong></div>${a.directions.includes('reach')?`<div><span>Средние просмотры</span><strong>${a.views===null?'Не указаны':number(a.views)}</strong></div><div><span>Аудитория в Казахстане</span><strong>${a.audienceKz?'Заявлена':'Нужно уточнить'}</strong></div>`:''}</section>${a.note?'<section class="detail-section"><h3>От кандидата</h3><p>'+esc(a.note)+'</p></section>':''}${a.question?'<section class="detail-section"><h3>Уточнение</h3><p>'+esc(a.question)+'</p>'+(a.answer?'<blockquote>'+esc(a.answer)+'</blockquote>':'<span class="fine">Ждём ответ в Telegram</span>')+'</section>':''}<details class="detail-section"><summary>История решения</summary>${(a.history||[]).map(e=>'<div class="history-item"><span>'+date(e.at)+'</span><p>'+esc(e.text)+'</p></div>').join('')||'<p class="fine">Пока только анкета.</p>'}</details></div><footer class="decision-bar">${['review','reserve'].includes(a.status)?btn('Выбрать',`data-decision="approve" data-id="${a.id}"`,'primary','check'):''}${a.status==='review'||a.status==='clarification'?btn('Уточнить',`data-decision="clarify" data-id="${a.id}"`,'secondary'):''}${a.status==='review'||a.status==='clarification'?btn('Пропустить',`data-decision="reject" data-id="${a.id}"`,'quiet'):''}${a.status==='approved'?btn('Товар отправлен',`data-decision="mark_sent" data-id="${a.id}"`,'primary','check'):''}${['reserve','rejected'].includes(a.status)?btn('Вернуть в отбор',`data-decision="reopen" data-id="${a.id}"`,'secondary'):''}</footer></section>`;}
export function candidateView(s){
 const a=s.mine[0],d=s.draft,c=s.campaign;
 if(a){
  const titles={review:'На рассмотрении',clarification:'Нужен ваш ответ',approved:'Вы выбраны',sent:'Товар отправлен',reserve:'Анкета в резерве',rejected:'Отбор завершён',withdrawn:'Анкета отозвана'};
  return `<section class="application-wrap submitted"><span class="eyebrow">${a.id}</span><h1>${titles[canonicalStatus(a.status)]||'Анкета получена'}</h1>
  <p>${a.status==='approved'?'Менеджер напишет вам в Telegram.':a.status==='sent'?'Детали отправки можно уточнить у менеджера.':a.status==='clarification'?'Менеджер задал вопрос по вашей анкете.':'Статус и ответ появятся в этом боте.'}</p>
  <div class="submitted-person"><strong>${esc(a.name)}</strong><span>${esc(a.city)} · ${LANGUAGES[a.language]}</span><div class="pills">${directions(a)}</div></div>
  ${a.status==='clarification'?`<blockquote class="candidate-question">${esc(a.question)}</blockquote><form data-form="answer" class="stack"><label>Ваш ответ<textarea name="answer" required rows="4"></textarea></label>${btn('Отправить ответ','type="submit"','primary','arrow')}<p class="form-error" role="alert"></p></form>`:''}
  ${a.portfolio.length?`<details class="brief-note"><summary>Мои работы</summary>${a.portfolio.map(workLink).join('')}</details>`:''}
  <details class="brief-note"><summary>Условия сотрудничества</summary><p>${esc(brandText(a.briefText||c.brief))}</p></details></section>`;
 }
 return `<section class="application-wrap"><h1>Анкета креатора</h1><details class="brief-note"><summary>Условия сотрудничества</summary><p>${esc(brandText(c.brief))}</p></details>
 ${!c.ready||!c.active?'<div class="empty"><h2>Набор закрыт</h2><p>Новые анкеты пока не принимаются.</p></div>':`<form data-form="application" class="application-form"><div class="form-progress" aria-label="Шаг ${s.step} из 2"><span class="${s.step===1?'active':''}">1 · О вас</span><span class="${s.step===2?'active':''}">2 · Работы</span></div>
 ${s.step===1?`<div class="stack"><label>Имя<input name="name" autocomplete="given-name" value="${esc(d.name||'')}" required placeholder="Как к вам обращаться"></label><div class="two-fields"><label>Город<select name="city">${CITIES.map(city=>`<option ${d.city===city?'selected':''}>${city}</option>`).join('')}</select></label><label>Язык роликов<select name="language">${Object.entries(LANGUAGES).map(([v,label])=>`<option value="${v}" ${d.language===v?'selected':''}>${label}</option>`).join('')}</select></label></div><fieldset><legend>Формат сотрудничества</legend>${[['ugc','Снимать для бренда','Размер блога не важен'],['reach','Публиковать у себя','Добавлю статистику просмотров']].map(([v,label,desc])=>`<label class="direction-option"><input type="checkbox" name="directions" value="${v}" ${d.directions.includes(v)?'checked':''}><span><strong>${label}</strong><small>${desc}</small></span></label>`).join('')}</fieldset>${btn('Далее','type="submit" name="intent" value="next"','primary full','arrow')}</div>`:
 `<div class="stack"><label>Ссылки на работы<textarea name="portfolio" rows="2" placeholder="До трёх ссылок, каждая с новой строки">${esc(d.portfolio||'')}</textarea><small>Reels, TikTok или видео с открытым доступом.</small></label><label>Опыт<select name="experience"><option value="brand" ${d.experience==='brand'?'selected':''}>Снимал(а) для брендов</option><option value="blog" ${d.experience==='blog'?'selected':''}>Снимаю для своего блога</option><option value="beginner" ${d.experience==='beginner'?'selected':''}>Первые проекты</option></select></label>
 ${d.directions.includes('reach')?`<label>Профиль<input type="url" name="profile" value="${esc(d.profile||'')}" required placeholder="https://..."></label><div class="two-fields"><label>Средние просмотры<input type="number" min="0" name="views" value="${esc(d.views||'')}"></label><label>Подписчики<input type="number" min="0" name="followers" value="${esc(d.followers||'')}"></label></div><label class="check-line"><input type="checkbox" name="audienceKz" ${d.audienceKz?'checked':''}>Основная аудитория — в Казахстане</label>`:''}
 <label>Срок съёмки после получения<select name="availabilityDays">${[3,7,14,30].map(n=>`<option value="${n}" ${Number(d.availabilityDays)===n?'selected':''}>В течение ${n} дней</option>`).join('')}</select></label>
 <label class="check-line"><input type="checkbox" name="closeup" required ${d.closeup?'checked':''}>Готов(а) снимать применение крупным планом</label><label class="check-line"><input type="checkbox" name="adult" required ${d.adult?'checked':''}>Мне исполнилось 18 лет</label><label class="check-line"><input type="checkbox" name="terms" required ${d.terms?'checked':''}>Прочитал(а) условия сотрудничества</label><label class="check-line"><input type="checkbox" name="consent" required ${d.consent?'checked':''}>Согласен(на) на обработку анкеты для отбора и связи${c.privacyUrl?' · <a href="'+esc(c.privacyUrl)+'" target="_blank" rel="noopener">Политика</a>':''}</label><div class="editor-actions">${btn('Назад','type="button" data-form-back','secondary')}${btn('Отправить анкету','type="submit" name="intent" value="send"','primary','arrow')}</div></div>`}
 <p class="form-error" role="alert"></p></form>`}</section>`;
}
export function welcome(s){
 return `<header class="topbar">${brand()}</header><main class="application-wrap welcome"><h1>Анкета креатора</h1><p>Откройте бота, чтобы заполнить анкету и получить ответ.</p><a class="button primary" href="${esc(formLink(s.botUsername))}">Открыть в Telegram ${icon('arrow')}</a></main>`;
}
